  "charmKindDescriptions": [
    "装備なし",
    "とある兵士が戦地に赴く際に\r\n身に着けていた護石。持ち主\r\nに幸運を呼び寄せるという。",
    "異国の闘士が勝利を祈願して\r\n作らせた護石。災いをはね\r\nのける力を持つという。",
    "武勲を挙げた騎士に与えられる\r\n誉れ高き護石。持つ者は栄光を\r\n手にするという。",
    "数百年にわたり王都を守り抜い\r\nた城塞の要石で作られた護石。\r\n不動の力が宿るという。",
    "その治世によって輝かしき黄金\r\n時代を作り上げた女王の護石。\r\n世を統べる者の英知が宿る。",
    "世界を手にする王の護石。\r\n身に着けた者は、賢なる\r\n知性と、剛なる力を持つ。",
    "龍の瞳で作られたという七色に\r\n輝く護石。自然界の頂点に君臨\r\nする龍の力が宿るとされる。",
    "災厄の世に闇を払い、救いの光\r\nをもたらした英雄の護石。淡い\r\n輝きが心に確かな希望を灯す。",
    "かつて歴史を動かした偉人達が\r\n手にしていた護石。石が持ち手\r\nを選ぶという伝説がある。",
    "天の恩恵を授かる奇跡の護石。\r\n見る者の本能を揺さぶる圧倒的\r\n存在感は、まさに天の賜物。"
  ],

